import { existsSync, readFileSync, renameSync, writeFileSync } from "node:fs";
import { dirname } from "node:path";
import { parse as parseYaml, stringify as stringifyYaml } from "yaml";
import type { z } from "zod";
import { NotFoundError, ValidationError } from "../core/errors.js";
import { ensureDir, type MePaths, mePaths } from "../core/paths.js";
import { MasterResume, Profile } from "./schema.js";

const MASTER_HEADER =
	"# Master resume, generated by `jh me ingest` (ids are stable; never renumber).\n" +
	"# Text edits are fine. Employer, title and dates are fixed facts. Metric statuses\n" +
	"# change only through `jh metrics confirm` (see metrics.md).\n";

/** Parse a YAML/JSON file and validate it; NotFoundError if missing, ValidationError if invalid. */
export function readValidated<S extends z.ZodType>(
	file: string,
	schema: S,
	label: string,
): z.infer<S> {
	if (!existsSync(file)) throw new NotFoundError(`${label} not found: ${file}`);
	let raw: unknown;
	try {
		raw = parseYaml(readFileSync(file, "utf8").replace(/^﻿/, ""));
	} catch (e) {
		throw new ValidationError(
			`${label} is not valid YAML: ${(e as Error).message}`,
			{
				file,
			},
		);
	}
	const parsed = schema.safeParse(raw ?? {});
	if (!parsed.success) {
		const issues = parsed.error.issues.map((i) => ({
			path: i.path.join("."),
			message: i.message,
		}));
		throw new ValidationError(`${label} is invalid (${file})`, issues);
	}
	return parsed.data;
}

/** Write via a temp file + rename so a crash never leaves a half-written file. */
export function writeFileAtomic(file: string, content: string): void {
	ensureDir(dirname(file));
	const tmp = `${file}.${process.pid}.tmp`;
	writeFileSync(tmp, content, "utf8");
	renameSync(tmp, file);
}

export function writeYaml(file: string, data: unknown, header = ""): void {
	writeFileAtomic(file, header + stringifyYaml(data, { lineWidth: 0 }));
}

export function loadProfile(paths: MePaths = mePaths()): Profile {
	return readValidated(paths.profile, Profile, "profile");
}

export function loadMaster(paths: MePaths = mePaths()): MasterResume {
	return readValidated(paths.masterResume, MasterResume, "master resume");
}

/** Serialize the master resume. Validates first, so a bad id can never be written. */
export function masterToYaml(m: MasterResume): string {
	const valid = MasterResume.parse(m);
	return MASTER_HEADER + stringifyYaml(valid, { lineWidth: 0 });
}

export function saveMaster(m: MasterResume, paths: MePaths = mePaths()): void {
	writeFileAtomic(paths.masterResume, masterToYaml(m));
}

/** Lowercase ASCII slug used in role ids ("Acme Analytics, Inc." -> "acme-analytics-inc"). */
export function slug(s: string, max = 40): string {
	const out = s
		.normalize("NFKD")
		.replace(/[̀-ͯ]/g, "")
		.toLowerCase()
		.replace(/[^a-z0-9]+/g, "-")
		.replace(/^-+|-+$/g, "")
		.slice(0, max)
		.replace(/-+$/g, "");
	return out || "x";
}

export function normSkill(s: string): string {
	return s.trim().toLowerCase().replace(/\s+/g, " ");
}

/** Every skill the user can claim: master skills, live bullet skills, profile tiers. */
export function allSkills(m: MasterResume, p?: Profile): Set<string> {
	const out = new Set<string>();
	const add = (s: string) => {
		const n = normSkill(s);
		if (n) out.add(n);
	};
	for (const s of m.skills) add(s);
	for (const role of m.roles)
		for (const b of role.bullets)
			if (!b.retired) for (const s of b.skills) add(s);
	const tiers = p?.skills;
	if (tiers)
		for (const s of [
			...(tiers.expert ?? []),
			...(tiers.proficient ?? []),
			...(tiers.familiar ?? []),
		])
			add(s);
	return out;
}

/** "2022-03" -> months since year 0. */
export function ymToMonths(ym: string): number {
	const [y = "0", mo = "1"] = ym.split("-");
	return Number(y) * 12 + (Number(mo) - 1);
}

export function endMonths(end: string, now: Date): number {
	return end === "present"
		? now.getUTCFullYear() * 12 + now.getUTCMonth()
		: ymToMonths(end);
}

/**
 * Years of experience: profile.experience_years when set above 0, otherwise the union of
 * all `role` intervals (overlaps counted once, projects ignored), floored.
 */
export function experienceYears(
	m: MasterResume,
	p?: Profile,
	now: Date = new Date(),
): number {
	if (typeof p?.experience_years === "number" && p.experience_years > 0)
		return p.experience_years;
	const spans = m.roles
		.filter((r) => r.kind === "role")
		.map((r) => [ymToMonths(r.start), endMonths(r.end, now) + 1] as const)
		.filter(([s, e]) => e > s)
		.sort((a, b) => a[0] - b[0]);
	let total = 0;
	let curStart = -1;
	let curEnd = -1;
	for (const [s, e] of spans) {
		if (s > curEnd) {
			total += curEnd - curStart;
			curStart = s;
			curEnd = e;
		} else if (e > curEnd) curEnd = e;
	}
	total += curEnd - curStart;
	return Math.floor(total / 12);
}

export interface FrontMatterDoc {
	data: unknown;
	body: string;
	hasFrontMatter: boolean;
}

/** Split `---\n<yaml>\n---\n<body>`; files without front matter return data null. */
export function readFrontMatter(text: string): FrontMatterDoc {
	const src = text.replace(/^﻿/, "");
	const m = src.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/);
	if (!m) return { data: null, body: src, hasFrontMatter: false };
	return {
		data: parseYaml(m[1] ?? "") ?? {},
		body: m[2] ?? "",
		hasFrontMatter: true,
	};
}
